SELECT CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, status, SUM(CASE WHEN carrier = 'FedEx' THEN cost ELSE 0 END) AS fedex_cost, SUM(CASE WHEN carrier = 'Flash' THEN 1 ELSE 0 END) AS flash_count, MAX(shipped_date) AS latest_shipped_date FROM shipments WHERE (cost < 65 AND delivered_date > '2023-12-23') OR shipped_date <= '2024-06-01' GROUP BY CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END, status HAVING SUM(CASE WHEN carrier = 'Flash' THEN 1 ELSE 0 END) > 76 ORDER BY latest_shipped_date, shipped_cohort, status LIMIT 20
